export type CatalogSection = {
  /** the page slug and the section's number on it, "page#3" */
  slug: string;
  name: string;
  /** the selling job the section does */
  job: string;
  /** the move, in full */
  note: string;
  img: string;
};

export const sectionsCatalog = [
  { slug: "yorkshire-college-planning-invitation-workshop-2#3", name: "Yorkshire College Planning", job: "Reviews", note: "A testimonial headed by a before/after number ('Reduced My EFC From $94,262 to $17,833') beside a photo of the real aid reports, with red and green labels on the two figures. Below it a second reviewer disarms the fear of a hidden pitch ('it wasn't a teaser, purely informational').", img: "/library/crop/catalog/yorkshire-college-planning-invitation-workshop-2/03.jpg" },
  { slug: "bay-crawl-space-foundation-repair-home#4", name: "BAY Crawl Space & Foundation Repair", job: "Plan picker", note: "Eight real symptom photos (a level on a sloped floor, a crack in drywall, a sticking door, mold on joists), each labelled with a plain symptom name. The buyer recognises their own problem, and a button sits right below.", img: "/library/crop/catalog/bay-crawl-space-foundation-repair-home/04.jpg" },
  { slug: "vessi-womens-weekend-marble-white#5", name: "Vessi", job: "Reviews", note: "A 4.67 score over 25,440 reviews with a star-bar breakdown and comfort and fit sliders. An auto-generated summary and a strip of customer photos and a video sit above filters and review cards. One card tells of dry feet in a downpour in Florence, so the fit doubt and the waterproof doubt are both answered in the reviewers' words.", img: "/library/crop/catalog/vessi-womens-weekend-marble-white/05.jpg" },
  { slug: "mrrooter-local#7", name: "Mr. Rooter Plumbing of Champaign", job: "Expectation", note: "A five-step dotted line with icons states the visit as promises: arrive on time, price before we start, mats and shoe covers, durable repairs, stand behind the work. Each can be checked at the door, and a Request Service button sits under it.", img: "/library/crop/catalog/mrrooter-local/07a-what-to-expect-from-a.jpg" },
  { slug: "simple-creator-co-made-to-sell-ad#4", name: "Simple Creator Co.", job: "Case studies", note: "One student's story laid out as a photo beside a short narrative, then three large figures ('0' product experience, '$20k' in a month, '90' days). The line 'same $17 mini-course you're looking at' ties her result to the buyer's exact purchase.", img: "/library/crop/catalog/simple-creator-co-made-to-sell-ad/04.jpg" },
  { slug: "javvy-rs01#13", name: "Javvy", job: "The offer", note: "A 'Reaching #11' line rewards the reader, then a dashed coupon-style card with a 'Fall Special' tab shows the product kit, a red 'up to 58% off', a button, a second countdown, a 'Sell-Out Risk: High' badge, free shipping and a 30-day guarantee. The button, deadline, scarcity and guarantee all sit in one box.", img: "/library/crop/catalog/javvy-rs01/13.jpg" },
  { slug: "primal-queen-tiktok#17", name: "Primal Queen", job: "Comparison", note: "A two-column table sets the product against green juice on thirteen rows, with check and X marks. The center column is a dark panel, and the rows flip at 'False Hype' so the rival wins only the negatives.", img: "/library/crop/catalog/primal-queen-tiktok/17.jpg" },
  { slug: "eight-sleep-pod-prospecting#7", name: "Eight Sleep", job: "Reviews", note: "A 4.5 score with a 1-5 star bar breakdown, filter chips by problem (Hot sleepers, Couples, Hot flashes, Insomnia) and six dated App Store reviews. The chips let the buyer filter reviews down to their own problem, and a few reviews are lukewarm, which lends credibility.", img: "/library/crop/catalog/eight-sleep-pod-prospecting/07.jpg" },
  { slug: "ag1-offers#4", name: "AG1 by Athletic Greens", job: "Proof", note: "A macro photo of a green powder dome on a glass dish sits beside three large percentages (70%, 73%, 10x), each under a label naming the biomarker. A small footnote gives the study population. The big numbers turn 'clinically backed' into specific, checkable results.", img: "/library/crop/catalog/ag1-offers/04.jpg" },
  { slug: "ag1#1", name: "AG1 \"best green powder offers\"", job: "First screen", note: "The headline reframes the product ('more than a greens powder') and sets a per-day price under $3. A receipt-style box sits directly below it: the pouch at $79 with $99 struck, three first-order extras each marked Free with a struck value, and a total. The button repeats the gift value.", img: "/library/crop/catalog/ag1/offer-strip-and-code-banner.jpg" },
  { slug: "highlevel-em-30-day-trial#14", name: "HighLevel", job: "Comparison", note: "A feature-by-feature table: each row names the tools it replaces with logos and a monthly price. It ends on a total of $7,111 per month for the other tools against $297 for HighLevel. Below it, a strip of review-site badges.", img: "/library/crop/catalog/highlevel-em-30-day-trial/14.jpg" },
  { slug: "creao-ai-home#2", name: "CREAO AI", job: "Demonstration", note: "A list of agent cards with status pills (Running, Scheduled, In review, Idle) sits beside a live run log that ends in a finished quote email with line items and a total, paused 'awaiting approval'. The buyer sees the work product, not a feature claim.", img: "/library/crop/catalog/creao-ai-home/02.jpg" },
  { slug: "mark-hyman-10-day-detox#11", name: "Mark Hyman", job: "The offer", note: "Three side-by-side plan cards, $67, $267 and a dark highlighted card with a struck-through $497 and $397. Each shows icon sums (guide + supplements + support), a checklist and a one-time-payment note.", img: "/library/crop/catalog/mark-hyman-10-day-detox/11.jpg" },
  { slug: "it-is-nick-miller-the-ai-creator-course-nick#15", name: "It Is Nick Miller", job: "Demonstration", note: "Two matching frames of the same instructor, 'Before AI' in a messy bedroom and 'After AI' on a city-view penthouse set, with the same pose and crop. A line below says all you need is a blank wall.", img: "/library/crop/catalog/it-is-nick-miller-the-ai-creator-course-nick/15.jpg" },
  { slug: "synthesia-sop#8", name: "Synthesia", job: "Demonstration", note: "A try-it block on dark ground: pick one of three avatars, type a script, press 'Create free AI video'. The large presenter beside it shows the output. The result arrives by email, so it also captures the lead.", img: "/library/crop/catalog/synthesia-sop/08.jpg" },
  { slug: "openart#1", name: "OpenArt", job: "First screen", note: "The first screen is a working chat box under a plain-verb headline. Rotating example prompts, three request chips, a 'Guide me' dropdown and a mic let a buyer who doesn't know what to ask start anyway. Trying comes before reading.", img: "/library/crop/catalog/openart/01a-headline-and-chat-box.jpg" },
  { slug: "snow-teeth-whitening-pen#10", name: "Snow", job: "Proof", note: "Three before/after photos of teeth in the same crop, each captioned with a first name and the product used. A line below says 'Photos from verified Snow customers. No filters applied.'", img: "/library/crop/catalog/snow-teeth-whitening-pen/10.jpg" },
  { slug: "base44#4", name: "Base44", job: "Reasons", note: "The eyebrow asks the buyer's fear ('Backend? Already done.'), and a build log beside a store mockup lists eight pieces written by name (login, user database, roles, checkout, shipping). 'Built in' becomes something to check against their own app.", img: "/library/crop/catalog/base44/04a-stage-panel-two-the-backend.jpg" },
  { slug: "ali-academy#14", name: "Ali Abdaal", job: "Objections", note: "The selling fear is named twice, as cold DMs and 'what if I'm not worth paying?'. The proof is a five-star review about anxiety, an arrow down to the Slack post where that same person's client paid $5,500 within a minute, and two more peer posts.", img: "/library/crop/catalog/ali-academy/14.jpg" },
  { slug: "ptya#3", name: "Part-Time YouTuber Academy (Ali Abdaal)", job: "Founder", note: "The founder tells his own before-and-after in the first person: 0 views to 100k subscribers to 1M, beside two photos (on stage, holding the play button plaque). A growth chart marked 'while working as a doctor' and a handwritten aside ('least natural on camera') share the reader's doubt.", img: "/library/crop/catalog/ptya/03-founder-story.jpg" },
  { slug: "pella-performance#5", name: "Pella", job: "Proof", note: "Two huge yellow figures on black (100,000 door cycles and 10,000 window cycles). Each has a plain-time translation ('3 times a day for more than 91 years') and the industry standard (10,000 and 8,000) under it. The big number, the human-scale translation and the benchmark make a durability claim concrete.", img: "/library/crop/catalog/pella-performance/05.jpg" },
  { slug: "physician-s-choice-digestive-enzymes-prebiotic-probiotic#9", name: "Physician's Choice", job: "Comparison", note: "A headline pricing the product at 26 cents a day, over a two-column checklist against 'everything else you've tried', where the rival items include a $40 GI copay and months of trial and error.", img: "/library/crop/catalog/physician-s-choice-digestive-enzymes-prebiotic-probiotic/09.jpg" },
  { slug: "farmersdog#4", name: "The Farmer", job: "Comparison", note: "Dark block with the old product's tricks struck through in red: 'Meals', 'Brown Pellets', 'Label Tricks', each with one concrete line ('made with beef can mean just 3% beef'). The direct-to-you model is given as the reason they can do better.", img: "/library/crop/catalog/farmersdog/04-the-old-way-struck-through.jpg" },
  { slug: "magicspoon-custom-bundle#1", name: "Magic Spoon", job: "Plan picker", note: "A three-step builder sits beside the product grid. Pick a size (6 Pack tagged 'Most Popular', 8 Pack 'Best Value', each with a savings %), fill empty dashed slots, then choose a frequency with Subscribe & Save preselected. The tags steer the buyer to a bigger box.", img: "/library/crop/catalog/magicspoon-custom-bundle/01.jpg" },
  { slug: "webflow-home#3", name: "Webflow", job: "Case studies", note: "A carousel of video-still cards. Each shows a named executive's face, a company logo, a large result figure ('20% increase in site-wide conversion', '$6M in cost savings annually') and a short quote with name and title. A 'Talk to sales' link closes the row. The result leads and the quote backs it.", img: "/library/crop/catalog/webflow-home/03.jpg" },
  { slug: "runway-aleph-2#6", name: "Runway", job: "Comparison", note: "Two same-framed clips side by side, 'Original video' and 'Edited using Aleph 2.0'. The woman in the mirror keeps her face and background and swaps only her glasses. The text names what rival tools get wrong (added cuts, altered objects).", img: "/library/crop/catalog/runway-aleph-2/06.jpg" },
  { slug: "runable-home#3", name: "Runable", job: "Case studies", note: "A tab picks the buyer type (small business, creator, everyday user), then three cards walk one owner through Plan, Build and Grow. Each card has a small mockup (chat, booking calendar, '+35%' stat), ending in a one-line quote from a studio owner.", img: "/library/crop/catalog/runable-home/03.jpg" },
  { slug: "arrae-tone-variety-pack#1", name: "Arrae", job: "First screen", note: "A flavor picker sits above three purchase options. The 3-month subscription is pre-selected, marked 'Best value, save 30%' with the old price struck through and a per-month price. Its perks are listed inside the card, and the other two options are bare, so the subscription looks like the obvious pick.", img: "/library/crop/catalog/arrae-tone-variety-pack/01a.jpg" },
  { slug: "jonesroad-foundation-epdp#4", name: "Jones Road Beauty", job: "Plan picker", note: "A grid of 30 real faces, one per shade, filterable by tone band (very pale to deep). Tapping one opens a large portrait with the shade name, an add-to-bag button and a quiz fallback, so the buyer matches shade by looking at someone like them.", img: "/library/crop/catalog/jonesroad-foundation-epdp/04.jpg" },
  { slug: "photoroom-enterprise-overview#3", name: "Photoroom", job: "Reasons", note: "Two crops of the same model in a green polo with a circle on the button. The left shows a malformed button with a red X, the right a correct one with a green check. The copy cites a 37% concern and returns, so a tiny AI error becomes a cost.", img: "/library/crop/catalog/photoroom-enterprise-overview/03.jpg" },
  { slug: "leaffilter-leaf-home-facebook-complete#1", name: "LeafFilter", job: "First screen", note: "The price question is the headline, and a one-tap YES/NO question about existing gutters is the first step. Committing costs one tap, and the answer routes the buyer to the right quote. A Trustpilot count sits beside the logo.", img: "/library/crop/catalog/leaffilter-leaf-home-facebook-complete/01.jpg" },
  { slug: "tyler-tometich-10dayviralvfxpro#1", name: "Tyler Tometich", job: "First screen", note: "A black countdown bar sits over a headline that names a hidden enemy (a 96.4% under-500-views statistic) and promises a daily view range. A giant-VFX video, one yellow CTA, a star row with student faces and a brand-logo strip follow on the same screen.", img: "/library/crop/catalog/tyler-tometich-10dayviralvfxpro/01.jpg" },
  { slug: "zapier-home#2", name: "Zapier", job: "How it works", note: "Two stacked feature rows pair a short pitch and collapsed feature accordions with a product visual. The first visual is three AI-tool icons with a cursor. The second is a mock AI note listing 'What went wrong / What changed' beside a flow diagram. Each row has its own two buttons.", img: "/library/crop/catalog/zapier-home/02.jpg" },
  { slug: "ixl-math#2", name: "IXL", job: "Plan picker", note: "Three package cards, each with a colored header and illustration, show a large discounted price over the struck-through list price. A 'Best value!' ribbon sits on the four-subject card and a 20%-off-for-new-families tag sits above the row. A Spanish add-on checkbox with its own struck-through price sits below the cards.", img: "/library/crop/catalog/ixl-math/02.jpg" },
  { slug: "mr-appliance-champaign#1", name: "Mr. Appliance", job: "First screen", note: "The hero card puts a headline, a 788-review and 4.6 rating tile and a booking button with 'Complete in under 2 minutes' over a kitchen photo. A thin ad-style 30-years strip sits below the hero.", img: "/library/crop/catalog/mr-appliance-champaign/01.jpg" },
  { slug: "ahs-quote-fb#1", name: "American Home Shield", job: "First screen", note: "A one-field ZIP start with 'Step 1 of 3' and a 'Next' button sits beside a red '50% Off Select Plans!' banner. The phone number is repeated as an alternative to the form. Committing feels small, and the discount gives a reason to start now.", img: "/library/crop/catalog/ahs-quote-fb/01.jpg" },
  { slug: "vuori-home#3", name: "Vuori", job: "Plan picker", note: "Three tall editorial tiles, each with a small kicker, a title and a 'Shop Now' link. One adds a 'Shorts Guide' link, so a buyer who isn't ready to buy can go to a guide instead.", img: "/library/crop/catalog/vuori-home/03.jpg" },
  { slug: "midas-ddcpage#1", name: "Midas", job: "First screen", note: "A big brand headline over a mechanic photo, with a ZIP-or-city store finder open as the first action. Three collapsed options sit under it (tires, coupons, estimate), so each buyer picks their own entry without leaving the first screen.", img: "/library/crop/catalog/midas-ddcpage/01.jpg" },
  { slug: "huel-huel-black-edition#1", name: "Huel", job: "First screen", note: "The gallery opens on a macro card, 40g protein, 27 vitamins, up to 11g fiber, set large beside the bag. Beside it, a flavor list shows a per-bbag price on each row and a plus button to add it. Choosing a flavor and adding to cart is one gesture.", img: "/library/crop/catalog/huel-huel-black-edition/01a.jpg" },
  { slug: "quince-home#1", name: "Quince", job: "First screen", note: "A thin bar promises 365-day free shipping and returns. Below it, a nav leads with a '$50 Cashmere' price-point link, and the hero sets three cashmere looks beside a short line and one dark button.", img: "/library/crop/catalog/quince-home/01.jpg" },
  { slug: "nuvia-dental-implant-center-national-eval-fb#1", name: "Nuvia Dental Implant Center", job: "First screen", note: "The first screen puts a one-question quiz (how many teeth are missing, four radio options) directly under a '24 hours' headline. A Google 5.0 badge with a review count sits above it and a TV-logo strip below. The first answer costs nothing and sorts the lead.", img: "/library/crop/catalog/nuvia-dental-implant-center-national-eval-fb/01.jpg" },
  { slug: "ibd-marketsurge#2", name: "Investor's Business Daily", job: "First screen", note: "The split hero puts a real chart on the right, annotated with pattern call-out boxes (Cup, Consolidation, with stage, pivot and depth). The buyer sees the product's output before reading a feature. Beside it, a $24.95 first-month button sits above a 'then $149.95/month' disclosure line.", img: "/library/crop/catalog/ibd-marketsurge/02.jpg" },
  { slug: "annie-miller-concepts-stronger-mc-2#2", name: "Annie Miller Concepts", job: "First screen", note: "The hero names the exact buyer (beginner to intermediate coaches) and the gap in their training ('Your cert didn't teach you this…but I'd love to'). The $27 price sits on the button, over the instructor's photo in her gym.", img: "/library/crop/catalog/annie-miller-concepts-stronger-mc-2/02.jpg" },
  { slug: "edx-msw-hero#1", name: "edX", job: "First screen", note: "A campus photo with the headline card on the left and a lead form card on the right, so the first screen has the pitch and the capture together. A deadline-and-no-fee bar sits above them. A navy band underneath puts a U.S. News badge beside start dates, rank and field hours.", img: "/library/crop/catalog/edx-msw-hero/01.jpg" },
  { slug: "dryer-vent-wizard-charlotte#1", name: "Dryer Vent Wizard", job: "First screen", note: "A technician in a branded van fills the hero. Under the headline sit a count of happy customers (623) and a 4.9/5 star rating, then a yellow Schedule Now button. Proof sits right beside the first button, and the phone number is set large in the nav.", img: "/library/crop/catalog/dryer-vent-wizard-charlotte/01.jpg" },
  { slug: "brilliant-mathstruggle#1", name: "Brilliant", job: "First screen", note: "The headline gives the product a job title ('personal tutor'). A looping interactive sine-wave graphic shows what that tutor does. Three big-number badges sit under it (accredited, 100,000+ 5-star reviews, 10 million+ learners). Two buttons split the visitor into 'I'm a learner' or 'I'm a parent or teacher'.", img: "/library/crop/catalog/brilliant-mathstruggle/01.jpg" },
  { slug: "aceable-drivers-ed-social#2", name: "Aceable", job: "Plan picker", note: "A row of pink state pills (California to Texas) is the course finder. Under it, a dark band titled 'The Aceable Advantage' sets six icon-tagged features beside three phone mockups.", img: "/library/crop/catalog/aceable-drivers-ed-social/02.jpg" },
  { slug: "procore-demo-b#5", name: "Procore", job: "The close", note: "A black closing band pairs a single orange 'Request a Demo' button with four star ratings from third-party sources: Software Advice, G2, the Apple App Store and Google Play. Each has a review count, so the last ask comes with outside proof right beside it.", img: "/library/crop/catalog/procore-demo-b/05.jpg" },
  { slug: "brex-credit-card#1", name: "Brex", job: "First screen", note: "A one-field work-email box with the button sits beside the headline and a bold black-on-orange card shot. A logo strip (Gong, DoorDash, Airtable) under a '30,000+ teams' line backs the claim before the buyer scrolls.", img: "/library/crop/catalog/brex-credit-card/01.jpg" },
  { slug: "garage-door-doctor-psm-allmkt#2", name: "Garage Door Doctor", job: "Reviews", note: "One long review in a speech bubble that names the booking, a 30-minute heads-up call and a thorough explanation. A row of trust badges (Google, Fully Insured, Nextdoor, BBB) sits beside it with a Schedule Online button.", img: "/library/crop/catalog/garage-door-doctor-psm-allmkt/02.jpg" },
  { slug: "college-hunks-hauling-junk-portland#1", name: "College Hunks Hauling Junk", job: "First screen", note: "The first screen puts Google 4.8 (1238 reviews) and Trustpilot 4.9 right under the headline and a four-item checklist. Two buttons sit next to them, 'Request a free quote' and 'Call now', and the photo shows uniformed crew greeting a smiling couple at their door.", img: "/library/crop/catalog/college-hunks-hauling-junk-portland/01.jpg" },
  { slug: "quran-memorization-guide-vsl-hifz#1", name: "Quran Memorization Guide", job: "First screen", note: "A VSL page with only a headline and a video. The headline calls the method 'forgotten' and puts a specific result in it (4 pages a day, full retention, for adults). An autoplaying video with a 'Click To Unmute' overlay then pulls the buyer into the pitch.", img: "/library/crop/catalog/quran-memorization-guide-vsl-hifz/01.jpg" },
  { slug: "adt-dealer#1", name: "ADT", job: "First screen", note: "The first screen asks one tap-question (Homeowner or Rental, an icon on each tile) above a single 'Get your Offer' button, so the first commitment is a tap that sorts the buyer. The form sits beside the headline.", img: "/library/crop/catalog/adt-dealer/01a-headline-and-the-own-or.jpg" },
  { slug: "warriorbabe-warriorbabe-quiz#1", name: "WarriorBabe", job: "Plan picker", note: "The quiz opens on one question with four big tappable age-band cards and a thin progress bar. The subline ties the question to the buyer's own body ('your hormones change with age') and promises tailoring, so answering feels like getting a personal plan.", img: "/library/crop/catalog/warriorbabe-warriorbabe-quiz/01.jpg" },
  { slug: "shetty-masterclass-lp#1", name: "Jay Shetty", job: "First screen", note: "A self-qualifying question headline ('Would you be a great life coach?') over a 'free workshop reveals the 5 signs' promise. It makes the visitor test themselves, and a two-field form and a first-person button ('Yes, I want to be a coach') sit beside the founder's portrait.", img: "/library/crop/catalog/shetty-masterclass-lp/01.jpg" },
  { slug: "efficient-coach-happiness-coach-2#2", name: "Efficient Coach", job: "The offer", note: "A Trustpilot 4.7 / 1050+ strip sits over a course-cover image, beside the struck-through 444 and 75 USD price. A short tick list (30-day refund, audio and PDF) leads to one button, then a row of five accreditation badges. A boxed-product mockup with callout arrows sits lower down.", img: "/library/crop/catalog/efficient-coach-happiness-coach-2/02a.jpg" },
  { slug: "safe-step-home#1", name: "Safe Step", job: "First screen", note: "A $2,000-off headline sits on a card over two bath photos, with the phone number and a 3-step tab form. Step 1 is a feature checkbox, so the first click is a preference, not contact data. A row of badges (lowest price, A+ rating, lifetime warranty) sits below.", img: "/library/crop/catalog/safe-step-home/01.jpg" },
  { slug: "sahil-bloom-subscribe#1", name: "Sahil Bloom", job: "First screen", note: "A one-field email form sits beside a phone mockup of a real issue ('The Most Powerful Life Hacks') with the author's face on it, so the buyer sees what arrives in the inbox. A '800,000+' subscriber count and a '2x weekly' cadence set expectations above the form.", img: "/library/crop/catalog/sahil-bloom-subscribe/01.jpg" },
  { slug: "mindvalley-masterclass#1", name: "Mindvalley", job: "First screen", note: "A full-bleed video still of the host looking into camera, with a headline that promises a result 'without the hustle'. The sub-line puts a number on the effort ('a written roadmap in 9 minutes'), and a yellow 'Reserve my spot' button sits beside a 'Watch trailer' button.", img: "/library/crop/catalog/mindvalley-masterclass/01a.jpg" },
  { slug: "guitar-challenge-lp#1", name: "Tony Polecastro", job: "First screen", note: "The whole page is one screen: a quoted identity-flip headline ('Stop Dabbling, Start Playing') names the buyer's flaw and promises its opposite. Two fields and an orange button sit directly under it, and a black bar above states the audience size.", img: "/library/crop/catalog/guitar-challenge-lp/01a.jpg" },
];
